begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.admin_set_rsvp(uuid,text,uuid)','execute'),'Guest cannot register manual answers');
select ok(not has_function_privilege('authenticated','public.admin_set_rsvp(uuid,text,uuid)','execute'),'Browser cannot bypass admin API');
select ok(has_function_privilege('service_role','public.admin_set_rsvp(uuid,text,uuid)','execute'),'Service may record verified admin answer');
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000000001','manual-admin@example.test'),('00000000-0000-4000-8000-000000000002','non-admin@example.test');
insert into public.admin_profiles(user_id) values('00000000-0000-4000-8000-000000000001');
create temp table manual_guest as select public.create_invitation('Invitado sin teléfono','',now()+interval '10 days') as link;
select throws_ok($$select public.admin_set_rsvp((select (link->>'id')::uuid from manual_guest),'accepted','00000000-0000-4000-8000-000000000002')$$,'P0001','FORBIDDEN','Non-admin actor rejected');
select throws_ok($$select public.admin_set_rsvp((select (link->>'id')::uuid from manual_guest),'pending','00000000-0000-4000-8000-000000000001')$$,'P0001','INVALID_INPUT','Cannot forge pending answer');
update public.rsvps set notes='Preferencia alimentaria original' where invitation_id=(select (link->>'id')::uuid from manual_guest);
update public.invitations set expires_at=now()-interval '1 day',revoked=true where id=(select (link->>'id')::uuid from manual_guest);
create temp table original_credential as select token_hash from private.invitation_credentials where invitation_id=(select (link->>'id')::uuid from manual_guest);
select is(public.admin_set_rsvp((select (link->>'id')::uuid from manual_guest),'accepted','00000000-0000-4000-8000-000000000001')->>'status','accepted','Admin confirms a person without phone, even after deadline or link revocation');
select is((public.admin_snapshot()->'metrics'->>'accepted')::integer,1,'Manual confirmation updates seat totals');
select is((select notes from public.rsvps where invitation_id=(select (link->>'id')::uuid from manual_guest)),'Preferencia alimentaria original','Guest notes preserved');
select is((select source from public.rsvp_events),'admin','Audit records manual source');
select is((select actor_user_id::text from public.rsvp_events),'00000000-0000-4000-8000-000000000001','Audit records verified admin identity');
select ok((select responded_at is not null from public.rsvps),'Response timestamp is recorded');
select is((select token_hash from private.invitation_credentials where invitation_id=(select (link->>'id')::uuid from manual_guest)),(select token_hash from original_credential),'Manual answer does not rotate invitation token');
select ok((select sent_at is null from public.invitations),'Manual answer does not mark an invitation sent automatically');
select public.admin_set_rsvp((select (link->>'id')::uuid from manual_guest),'accepted','00000000-0000-4000-8000-000000000001');
select is((select count(*)::integer from public.rsvp_events),1,'Identical retry has no duplicate audit event');
create temp table manual_table as select public.create_seating_table('Mesa Manual',2) as data;
select public.assign_seating_guests((select (data->>'id')::uuid from manual_table),array[(select (link->>'id')::uuid from manual_guest)]);
select public.admin_set_rsvp((select (link->>'id')::uuid from manual_guest),'declined','00000000-0000-4000-8000-000000000001');
select is((select count(*)::integer from public.seating_assignments),1,'Manual decline retains the seat for administrator review');
select is((public.admin_snapshot()->'metrics'->>'declined')::integer,1,'Manual rejection updates metrics');
update public.invitations set archived_at=now() where id=(select (link->>'id')::uuid from manual_guest);
select throws_ok($$select public.admin_set_rsvp((select (link->>'id')::uuid from manual_guest),'accepted','00000000-0000-4000-8000-000000000001')$$,'P0001','INVITATION_ARCHIVED','Archived invitation cannot be manually confirmed');
update public.invitations set archived_at=null,revoked=false,expires_at=now()+interval '10 days' where id=(select (link->>'id')::uuid from manual_guest);
select public.submit_rsvp(encode(extensions.digest((select link->>'token' from manual_guest),'sha256'),'hex'),'accepted','Guest updated notes');
select is((select source from public.rsvp_events order by id desc limit 1),'guest','Guest responses still have guest audit source');
select ok((select actor_user_id is null from public.rsvp_events order by id desc limit 1),'Guest does not get admin identity');
select ok(not(public.resolve_invitation(encode(extensions.digest((select link->>'token' from manual_guest),'sha256'),'hex')) ?| array['source','actor_user_id']),'Guest response does not expose admin audit');
select throws_ok($$select public.admin_set_rsvp('00000000-0000-4000-8000-000000000099','accepted','00000000-0000-4000-8000-000000000001')$$,'P0001','NOT_FOUND','Unknown invite rejected');
select * from finish();
rollback;
